import {renderProductionMatrix,readProductionMatrix,syncProductionMatrix} from './domestic-production-ui.js';
import {GROWTH_DATA} from './growth-data.js';
import {RESOURCE_LABELS} from './economy.js';
import {ACTION_CARDS} from './basic-actions.js';
export function renderDomesticForm(s,id,card={}){const p=s.players[s.current],level=p.growth.length+1;
 return `<section id="basic-form" data-card-id="${id}" class="flow-panel"><b>发展战略 · 自动结算</b><label>选择效果<select id="basic-domestic">${card.domesticMode!=='growth'?`<option value="produce">生产至多${card.maxProduction??3}种不同资源</option>`:''}${card.domesticMode!=='produce'?'<option value="growth">取得下一级发展牌</option>':''}</select></label><div id="domestic-production"><p>${card.exhaustAllyLabel?'先横置'+card.exhaustAllyLabel+'。':''}初级资源先生产，再加工所选资源。</p>${renderProductionMatrix(s,card)}</div><div id="domestic-growth" hidden><label>第${level}级发展牌<select id="basic-growth">${s.growth.filter(cid=>GROWTH_DATA[cid]?.level===level).map(cid=>{const g=GROWTH_DATA[cid];return `<option value="${cid}">${g.name} · ${g.services}服务${g.money?'＋'+g.money+'资金':''}${g.diplomacy?'＋'+g.diplomacy+'外交':''}${g.goods?'＋'+g.goods+'消费品':''}${g.armies?'＋'+g.armies+'待命军队':''}${g.primary?'＋任意'+g.primary+'初级资源':''}${g.discard?'＋弃1张手牌':''} · ${g.effect==='dominance'?2*(s.round-1):g.vp}分</option>`;}).join('')||'<option value="">没有可自动购入的下一级发展牌</option>'}</select></label>${card.serviceMoneyCost?`<label>用资金替代服务<input id="growth-service-money" type="number" min="0" value="0"></label><p>每点服务可用${card.serviceMoneyCost}资金替代。</p>`:''}<p class="minor">请选择下一级发展牌，费用与即时效果会显示在下方。</p><div id="growth-face"></div><label id="growth-discard-field" hidden>高层更替 · 弃置手牌支付费用<select id="growth-discard"><option value="">请选择另一张手牌</option>${p.hand.filter(cid=>cid!==id).map(cid=>`<option value="${cid}">${cid}</option>`).join('')}</select></label><fieldset id="growth-primary" hidden><legend>资源集约 · 支付合计5份初级资源</legend>${RESOURCE_LABELS.slice(0,3).map((name,k)=>`<label>${name}（库存${p.resources[k]}）<input type="number" data-growth-primary="${k}" min="0" max="${p.resources[k]}" value="0"></label>`).join('')}</fieldset><p id="growth-effect-note"></p></div><p id="basic-preview" aria-live="polite"></p><button id="commit-basic" data-card-action="playBasicCard" data-id="${id}">结算并完成本次行动</button></section>`;
}
export function readDomesticForm(){return {primary:document.querySelector('#growth-primary')?.hidden?undefined:[...document.querySelectorAll('[data-growth-primary]')].map(el=>Number(el.value)),growthDiscard:document.querySelector('#growth-discard-field')?.hidden?undefined:document.querySelector('#growth-discard')?.value,serviceMoney:Number(document.querySelector('#growth-service-money')?.value||0),domestic:document.querySelector('#basic-domestic')?.value,growthId:document.querySelector('#basic-growth')?.value,upgrades:[],production:readProductionMatrix()};}
export function updateDomesticForm(s,cards){const mode=document.querySelector('#basic-domestic');if(!mode)return;const growth=mode.value==='growth';document.querySelector('#domestic-growth').hidden=!growth;document.querySelector('#domestic-production').hidden=growth;
 syncProductionMatrix();
 const industry=growth&&GROWTH_DATA[document.querySelector('#basic-growth')?.value]?.effect==='industry';document.querySelector('#commit-basic').textContent=industry?'确认购买产业发展':document.querySelector('#basic-form').dataset.sequence?'结算并继续':'结算并完成本次行动';
 const id=document.querySelector('#basic-growth')?.value,g=GROWTH_DATA[id];document.querySelector('#growth-primary').hidden=!g?.primary;document.querySelector('#growth-discard-field').hidden=!g?.discard;for(const option of document.querySelector('#growth-discard').options)if(option.value)option.textContent=cards[option.value]?.name||ACTION_CARDS[option.value]?.name||'能力牌';const substitute=document.querySelector('#growth-service-money');if(substitute)substitute.max=g?.services??0;document.querySelector('#growth-face').innerHTML=g&&cards[id]?`<img class="viewerimage" src="${cards[id].image}" alt="${g.name}">`:'';document.querySelector('#growth-effect-note').textContent=g?(g.effect==='industry'?'':g.effect==='battlefield'?'购入立即生效。':g.level>s.round?'能力第'+g.level+'轮开始生效。':'能力现已生效。')+(g.effect==='battlefield'?'立即抽2张本方战略资产留1张并获牌面分数，再可无需盖手牌使用1张未使用资产。':g.effect==='manual'?'此牌的主动能力仍需手动处理；购入费用与分数自动结算。自动购入将结束行动，如需在本次行动内衔接额外效果，请改用手动出牌。':g.effect==='quick'?'准备阶段确认焦点时，可选择花5资金获得军队或免费移动1支军队。':g.effect==='income'?'研究开始时选两张剩余手牌，再领取一次上半部奖励；不额外获得研究力。':g.effect==='living'?'繁荣提升自动少付1消费品、多得1分（包含牌面提升效果）。':g.effect==='dominance'?'购入时按已完成轮数获得分数；生效后，每次行动放置过影响力额外得1分。':g.effect==='authority'?'地区计分时，同影响力优先于其他玩家；不改变目标条件或多数计分。':g.effect==='nuclear'?'在所有地区自动增加1威胁、1防御，包括没有本方军队的地区。':g.effect==='industry'?'购买后选择两种产能各提升1，不额外领取初级资源。':g.effect==='draw'?'灵活战术的每轮额外抽牌自动执行。':g.effect==='ready'?'选择焦点时额外重整1盟国自动计入。':g.effect==='open'?'结盟操作框可选择追加第二个国家。':g.effect==='resilience'?'添加影响力时可选择前后转换本方临时影响力。':g.effect==='extra'?'每轮首次行动追加一张牌，购入后立即检查资格。':['exchange','trim','leadership','efficiency','cooperation'].includes(g.effect)?'在本方发展牌区点击此牌使用每轮能力。':'此牌仅提供分数。'):'';
}
export function domesticSummary(r){return r.effect==='production'?`生产：${r.produced.map(x=>RESOURCE_LABELS[x.key]+' '+x.quantity).join('、')||'无'}。超限折现${r.overflow}资金；结算后资金${r.money}。`:`支付${r.services}服务、${r.diplomacy}外交、${r.cost}资金${r.goods?"、"+r.goods+"消费品":""}${r.armies?"、"+r.armies+"待命军队":""}${r.primary?.length?"、"+r.primary.map((n,k)=>n+RESOURCE_LABELS[k]).join("、"):""}${r.growthDiscard?"，另弃置1张手牌":""}；获得${r.growthVP}分。${r.pendingIndustry?'购买后选择产能。':r.active?'能力现已生效。':'能力第'+r.growth.level+'轮生效。'}`;}
